import { readFileSync } from "node:fs";

// Bundled routable areas: county seats and București zones, generated by
// scripts/build-cities.py. Selection uses only these bounds; no city is named in code.
const INDEX = new URL(
  "../../mobile/assets/data/cities/index.json",
  import.meta.url,
);

const inside = (p, b) =>
  p.longitude >= b[0] &&
  p.longitude <= b[2] &&
  p.latitude >= b[1] &&
  p.latitude <= b[3];
const centre = (b) => ({
  longitude: (b[0] + b[2]) / 2,
  latitude: (b[1] + b[3]) / 2,
});
/** Distance to the nearest edge, in degrees scaled for latitude; larger is more interior. */
function depth(p, b) {
  const k = Math.cos((p.latitude * Math.PI) / 180);
  return Math.min(
    (p.longitude - b[0]) * k,
    (b[2] - p.longitude) * k,
    p.latitude - b[1],
    b[3] - p.latitude,
  );
}

export class CityCatalog {
  constructor(index) {
    if (index?.schema_version !== 1 || !Array.isArray(index.areas))
      throw Error("Invalid city index");
    this.areas = index.areas.filter(
      (a) =>
        typeof a.id === "string" &&
        /^[a-z0-9-]+$/.test(a.id) &&
        typeof a.file === "string" &&
        Array.isArray(a.bounds) &&
        a.bounds.length === 4 &&
        a.bounds.every(Number.isFinite) &&
        a.bounds[0] < a.bounds[2] &&
        a.bounds[1] < a.bounds[3],
    );
    this.byId = new Map(this.areas.map((a) => [a.id, a]));
  }
  static load(url = INDEX) {
    return new CityCatalog(JSON.parse(readFileSync(url, "utf8")));
  }
  get(id) {
    return this.byId.get(id) ?? null;
  }
  /** The area holding a point; overlapping zones choose the one where it is most interior. */
  at(p) {
    let best = null,
      bestDepth = -Infinity;
    for (const a of this.areas) {
      if (!inside(p, a.bounds)) continue;
      const d = depth(p, a.bounds);
      if (d > bestDepth) {
        best = a;
        bestDepth = d;
      }
    }
    return best;
  }
  /**
   * True when a whole viewport lies inside one bundled area, or each corner lies in
   * a zone of the same split city (the zones overlap by more than the viewport margin).
   */
  covers(bounds) {
    if (
      this.areas.some(
        (a) =>
          bounds[0] >= a.bounds[0] &&
          bounds[1] >= a.bounds[1] &&
          bounds[2] <= a.bounds[2] &&
          bounds[3] <= a.bounds[3],
      )
    )
      return true;
    const corners = [
      [bounds[0], bounds[1]],
      [bounds[0], bounds[3]],
      [bounds[2], bounds[1]],
      [bounds[2], bounds[3]],
    ].map(([longitude, latitude]) => this.at({ longitude, latitude }));
    return (
      corners.every((a) => a?.zone) &&
      new Set(corners.map((a) => a.city)).size === 1 &&
      // Neighbouring zones only; a viewport this wide is beyond building budgets anyway.
      corners.every(
        (a) =>
          Math.abs(a.zone[0] - corners[0].zone[0]) <= 1 &&
          Math.abs(a.zone[1] - corners[0].zone[1]) <= 1,
      )
    );
  }
  /**
   * Areas needed for a walk: one area holding both ends, or two adjacent zones of a split
   * city (side or corner neighbours). Returns null when no bundled graph connects them.
   */
  forRoute(a, b) {
    const both = this.areas
      .filter((x) => inside(a, x.bounds) && inside(b, x.bounds))
      .sort(
        (x, y) =>
          Math.min(depth(a, y.bounds), depth(b, y.bounds)) -
          Math.min(depth(a, x.bounds), depth(b, x.bounds)),
      );
    if (both.length) return [both[0]];
    const from = this.at(a),
      to = this.at(b);
    if (
      from?.zone &&
      to?.zone &&
      from.city === to.city &&
      Math.abs(from.zone[0] - to.zone[0]) <= 1 &&
      Math.abs(from.zone[1] - to.zone[1]) <= 1
    )
      return [from, to];
    return null;
  }
  summary() {
    const cities = new Map();
    for (const a of this.areas) {
      const c = cities.get(a.city) ?? {
        id: a.city,
        name: a.name.split(" · ")[0],
        areas: 0,
        bounds: [...a.bounds],
        centre: null,
        heights_year: a.heights_year ?? null,
      };
      c.areas++;
      c.bounds = [
        Math.min(c.bounds[0], a.bounds[0]),
        Math.min(c.bounds[1], a.bounds[1]),
        Math.max(c.bounds[2], a.bounds[2]),
        Math.max(c.bounds[3], a.bounds[3]),
      ];
      c.centre = centre(c.bounds);
      cities.set(a.city, c);
    }
    return [...cities.values()];
  }
}
